@extends('layouts.app') @section('title','Your cart — Shoply') @section('content')<section class="mx-auto max-w-5xl px-4 py-12"><h1 class="text-4xl font-black">Your cart</h1>@if($items->isEmpty())<div class="mt-8 rounded-2xl border bg-white p-12 text-center"><p class="text-slate-500">Your cart is empty.</p><a href="{{route('products')}}" class="mt-5 inline-block rounded-xl bg-blue-600 px-6 py-3 font-bold text-white">Start shopping</a></div>@else<div class="mt-8 space-y-4">@foreach($items as $item)<div class="flex items-center gap-4 rounded-2xl border bg-white p-4"><img src="{{$item['image']}}" class="h-20 w-20 rounded-xl object-cover"><div class="min-w-0 flex-1"><div class="font-bold">{{$item['name']}}</div><div class="text-sm text-slate-500">₦{{number_format($item['price'],2)}} each</div></div><form method="post" action="{{route('cart.update',$item['id'])}}" class="flex gap-2">@csrf @method('PATCH')<input name="quantity" type="number" min="1" max="{{$item['stock']}}" value="{{$item['quantity']}}" class="w-20 rounded-xl border px-3 py-2"><button class="rounded-xl border px-3 font-bold">Update</button></form><div class="w-28 text-right font-black">₦{{number_format($item['price']*$item['quantity'],2)}}</div><form method="post" action="{{route('cart.remove',$item['id'])}}">@csrf @method('DELETE')<button class="text-sm font-bold text-red-600">Remove</button></form></div>@endforeach</div><div class="mt-8 flex flex-col items-end"><div class="text-2xl font-black">Total: ₦{{number_format($total,2)}}</div><a href="{{auth()->check()?route('checkout'):route('login')}}" class="mt-4 rounded-xl bg-blue-600 px-7 py-3 font-bold text-white">Checkout</a></div>@endif</section>@endsection
